-- Carrier logos (redrawn as SVG; sources in supabase/seed/carrier-logos/) for carriers on the markets list that had none.
with l as (select '{"Chubb": "data:image/svg+xml;base64,", "Steadily": "data:image/svg+xml;base64,", "SES Risk Solutions": "data:image/svg+xml;base64,", "Obie": "data:image/svg+xml;base64,"}'::jsonb logos)
update public.reference_data r set data = (
  select jsonb_agg(case when jsonb_typeof(mk->'carriers') = 'array' then jsonb_set(mk, '{carriers}', (
      select coalesce(jsonb_agg(case when l.logos ? (c->>'name') and coalesce(c->>'logo', '') = '' then c || jsonb_build_object('logo', l.logos->>(c->>'name')) else c end order by o2), '[]'::jsonb)
      from jsonb_array_elements(mk->'carriers') with ordinality x(c, o2))) else mk end order by o1)
  from jsonb_array_elements(r.data) with ordinality y(mk, o1))
from l where r.key = 'markets'
returning r.agency_id, (select count(*) from jsonb_array_elements(r.data) mk, jsonb_array_elements(mk->'carriers') c where c->>'name' in ('Chubb','Steadily','SES Risk Solutions','Obie') and c->>'logo' like 'data:image/svg%') logos_set;
